+    if (use_japanese) {
+        return japanese;
+    }
+    return chars;
+}
+
+static int get_color_index(void) {
+    if (rainbow_mode) {
+        static int hue = 0;
+        hue = (hue + 1) % 360;
+        int r = (hue / 60) % 6;
+        int g = (hue / 60 + 2) % 6;
