+            int len = strlen(cs);
+        }
+    }
+}
+
+static void run(void) {
+    set_termios();
+    resize_term();
+    
+    if (linux_mode) {
+        printf("\033]1000;matrix.fnt\007");
+    }
+    
+    if (lock_mode) {
+        printf("\033[?1049h");
+    }
+    
+    clear_screen();
+    
+    if (message_set) {
+        print_centered_message(message);
+    }
+    
+    init_char_set();
+    
